-- Bulk merge of wrestler duplicates
-- 1,264 groups with at most one copy having live references.
-- Generated: 2026-08-02T19:42:34.020Z

BEGIN;

CREATE TEMP TABLE wrestler_merge_map (
  dupe_id   uuid,
  keep_id   uuid
);


-- Remap references
UPDATE public.tournament_entries
SET wrestler_id = m.keep_id
FROM wrestler_merge_map m
WHERE wrestler_id = m.dupe_id;

UPDATE public.dual_meet_matches
SET wrestler_a_id = m.keep_id
FROM wrestler_merge_map m
WHERE wrestler_a_id = m.dupe_id;

UPDATE public.dual_meet_matches
SET wrestler_b_id = m.keep_id
FROM wrestler_merge_map m
WHERE wrestler_b_id = m.dupe_id;

UPDATE public.dual_meet_matches
SET winner_id = m.keep_id
FROM wrestler_merge_map m
WHERE winner_id = m.dupe_id;

-- tournament_bouts.wrestler1_id / wrestler2_id also FK-reference wrestlers
-- (constraint is named nj_wrestler1_id_fkey from a historical column rename)
UPDATE public.tournament_bouts
SET wrestler1_id = m.keep_id
FROM wrestler_merge_map m
WHERE wrestler1_id = m.dupe_id;

UPDATE public.tournament_bouts
SET wrestler2_id = m.keep_id
FROM wrestler_merge_map m
WHERE wrestler2_id = m.dupe_id;

-- tournament_placements.wrestler_id also FK-references wrestlers
-- (constraint named tournament_placements_nj_wrestler_id_fkey from historical rename)
UPDATE public.tournament_placements
SET wrestler_id = m.keep_id
FROM wrestler_merge_map m
WHERE wrestler_id = m.dupe_id;

-- Delete the duplicate records
DELETE FROM public.wrestlers
WHERE id IN (SELECT dupe_id FROM wrestler_merge_map);

COMMIT;
